import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform, mix, float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-0-label-node';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const assetUrl = '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader.load(assetUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = { w: 512, h: 320 };
  const uvScale = vec2(atlasRect.w / atlasSize.w, atlasRect.h / atlasSize.h);
  const uvOffset = vec2(atlasRect.x / atlasSize.w, atlasRect.y / atlasSize.h);
  const scaledUV = uv().mul(uvScale).add(uvOffset);

  const grainAmount = uniform(0.035);
  const baseColor = texture(map, scaledUV);

  const noise = float(
    Math.random()
  );

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = mix(baseColor, baseColor.add(noise.mul(grainAmount)), 0.5);

  const width = 1.6;
  const height = width * (atlasRect.h / atlasRect.w);
  const geometry = new THREE.PlaneGeometry(width, height);
  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'pricing-card-3-label-plane';
  group.add(plane);

  const textMesh = createTextMesh({
    text: 'Pricing 3',
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: config?.visual?.colors?.paper || '#e8ecf2',
    anchor: 'center',
    fontAtlas: ctx.fontAtlas,
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) {
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach((m) => m.dispose());
      } else {
        textMesh.material.dispose();
      }
    }
    group.userData.handlers = {};
  };

  return group;
}
